type Analytics = {
  totalViews: number
  activeUsers: number
  bounceRate: number
}

type Notification = {
  id: string
  message: string
  read: boolean
}

type NotificationsPayload = {
  notifications: Notification[]
}

type Settings = {
  siteName: string
  timezone: string
  emailDigest: boolean
}

// Parallel data fetching (same pattern as getParallelData in page.tsx)
async function getDashboardData() {
  try {
    const [analytics, notificationsPayload, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json() as Promise<Analytics>),
      fetch('/api/notifications').then(
        (r) => r.json() as Promise<NotificationsPayload>,
      ),
      fetch('/api/settings').then((r) => r.json() as Promise<Settings>),
    ])

    return {
      analytics,
      notifications: notificationsPayload.notifications ?? [],
      settings,
    }
  } catch {
    return {
      analytics: { totalViews: 0, activeUsers: 0, bounceRate: 0 },
      notifications: [] as Notification[],
      settings: {
        siteName: 'Dashboard',
        timezone: 'UTC',
        emailDigest: false,
      },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()
  const unreadCount = notifications.filter((n) => !n.read).length

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section aria-labelledby="analytics-heading">
        <h3 id="analytics-heading">Analytics</h3>
        <ul>
          <li>Total views: {analytics.totalViews.toLocaleString()}</li>
          <li>Active users: {analytics.activeUsers.toLocaleString()}</li>
          <li>Bounce rate: {(analytics.bounceRate * 100).toFixed(1)}%</li>
        </ul>
      </section>

      <section aria-labelledby="notifications-heading">
        <h3 id="notifications-heading">
          Notifications
          {unreadCount > 0 ? ` (${unreadCount} unread)` : ''}
        </h3>
        {notifications.length === 0 ? (
          <p>No notifications</p>
        ) : (
          <ul>
            {notifications.map((n) => (
              <li key={n.id}>
                <span style={{ fontWeight: n.read ? 'normal' : 'bold' }}>
                  {n.message}
                </span>
                {n.read ? ' (read)' : ''}
              </li>
            ))}
          </ul>
        )}
      </section>

      <section aria-labelledby="settings-heading">
        <h3 id="settings-heading">Settings</h3>
        <ul>
          <li>Site name: {settings.siteName}</li>
          <li>Timezone: {settings.timezone}</li>
          <li>Email digest: {settings.emailDigest ? 'On' : 'Off'}</li>
        </ul>
      </section>
    </div>
  )
}

